// Falls back to the deterministic Grammar QC Precheck output if the AI
// checker call failed or didn't return usable JSON - never lets a bad
// checker response break the run.
const original = $node("Lightweight Fact Lookup").json;

function extractText(b){
  try {
    return b?.candidates?.[0]?.content?.parts?.[0]?.text
        ?? b?.choices?.[0]?.message?.content
        ?? '';
  } catch(e){ return ''; }
}

let raw = extractText($json);
raw = String(raw || '').replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();

function tryParse(s){ try { return JSON.parse(s); } catch(e) { return null; } }

let fixed = tryParse(raw);

const valid = fixed && fixed.title && fixed.topic && fixed.description
  && Array.isArray(fixed.tags) && Array.isArray(fixed.scenes)
  && fixed.scenes.length === (original.scenes ? original.scenes.length : 5)
  && fixed.scenes.every(s => s && s.voice && s.image_prompt);

const finalData = valid ? fixed : original;

return { json: {
  title: finalData.title,
  topic: finalData.topic,
  hook: finalData.hook || (finalData.scenes[0] ? finalData.scenes[0].voice : ''),
  description: finalData.description,
  tags: finalData.tags,
  scenes: finalData.scenes.map((s, i) => ({ ...s, scene: i + 1 })),
  factCheckApplied: valid
} };

const rows = items.map(i => i.json).filter(Boolean);

function norm(s){ return String(s||'').toLowerCase().trim(); }

const usedTitles   = rows.map(r => norm(r.title)).filter(Boolean);
const usedTopics   = rows.map(r => norm(r.topic)).filter(Boolean);
const usedHooks    = rows.map(r => norm(r.hook)).filter(Boolean);
const usedEntities = rows.map(r => norm(r.entities)).filter(Boolean);
const usedDescs    = rows.map(r => norm(r.description)).filter(Boolean);

const categories = ['world history mysteries','ancient civilizations & lost cities','human psychology & behavior','language & linguistics facts','mathematics & number theory','world geography & extreme places','economics & how money works','philosophy & big ideas','law & justice systems explained','political systems & government','space & astronomy','earth science & natural disasters','human body & anatomy','animal kingdom & wildlife biology','world religions & mythology','art history & famous artworks','architecture & engineering marvels','literature & famous authors','computer science & how technology works','military history & famous battles','medicine & health science','food science & nutrition facts','environmental science & climate change','famous scientists & discoveries','world cultures & traditions','archaeology & forgotten civilizations','forensic science & crime investigation','sports science & human performance','ocean & marine biology','weather & meteorology','world currencies & trade history','biggest disasters in history','learning science & memory hacks','world records & human extremes','folklore & legends explained','landmark scientific experiments','space exploration & missions','geology & deep earth history','chemistry in everyday life','physics in everyday life','artificial intelligence & future tech','renewable energy & sustainability','ancient egypt & pyramids','world war history','great explorers & expeditions','inventions that changed the world','famous philosophers & their ideas','how languages evolved','astronomy myths vs facts','ancient wonders of the world','unsolved quantum physics anomalies','bizarre deep sea creatures','forgotten historical empires','psychological paradoxes','mathematical impossibilities in nature','extreme planetary weather','bizarre ancient medical practices','microscopic world secrets','cryptography and lost codes','weird evolutionary traits','dark matter and astrophysics mysteries','rare geological formations'];

const wf = $getWorkflowStaticData('global');
if (typeof wf.runCounter !== 'number') wf.runCounter = 0;
wf.runCounter++;
const counter = wf.runCounter;
const category = categories[counter % categories.length];

function fisherYatesSample(arr, n){
  const a = arr.slice();
  const len = Math.min(n, a.length);
  for (let i = a.length - 1; i > a.length - 1 - len; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a.slice(a.length - len);
}

// Strategy: always keep the MOST RECENT items (catches near-term repeats reliably),
// then top it up with a random sample from older history (catches long-tail repeats)
// without ever exceeding a size small/free models can actually read.
function buildBanBlock(list, recentN, randomN){
  const unique = [...new Set(list)];
  const recent = unique.slice(-recentN);
  const older  = unique.slice(0, Math.max(0, unique.length - recentN));
  const randomOlder = fisherYatesSample(older, randomN);
  return [...new Set([...recent, ...randomOlder])];
}

const banListArr   = buildBanBlock([...usedTopics, ...usedTitles], 250, 150); // cap ~400 entries
const hookBanArr    = buildBanBlock(usedHooks, 150, 100);                      // cap ~250 entries
const entityBanArr  = buildBanBlock(usedEntities.flatMap(e => e.split(',').map(x=>x.trim()).filter(Boolean)), 150, 100);
const summaryBanArr = buildBanBlock(usedDescs, 100, 80);                       // feeds AI Semantic Duplicate Check

const banList    = banListArr.join(' | ');
const hookBan     = hookBanArr.join(' | ');
const entityBan   = entityBanArr.join(', ');
const summaryBan  = summaryBanArr.join(' | ');

const trendingContext = wf.trendingContext || '';

return [{ json: { category, counter, banList, hookBan, entityBan, summaryBan, usedCount: rows.length, trendingContext } }];

const meta = $node("Parse JSON").json;
const tags = Array.isArray(meta.tags)?meta.tags:['science','technology','shorts'];
const title=(meta.title||'Amazing Facts').slice(0,95);
let description=`${meta.description||title}\n\n#shorts #science #technology #facts\n\n${tags.map(t=>'#'+String(t).replace(/\s+/g,'')).join(' ')}`;
if(description.length>4900)description=description.slice(0,4900);
let tagList=[],total=0;
for(const t of tags){const s=String(t);if(total+s.length+1>480)break;tagList.push(s);total+=s.length+1;}
if(tagList.length===0)tagList=['science','technology','shorts'];
const publishAt=new Date(Date.now()+2*60*60*1000).toISOString();
return {json:{title,topic:meta.topic||title,description,tags:tagList,publishAt}};

const wf = $getWorkflowStaticData('global');
if (typeof wf.dupAttempts !== 'number') wf.dupAttempts = 0;

const data = $json;

// ---------------- helpers ----------------

const STOPWORDS = new Set(['the','a','an','of','in','on','how','why','what','is','are','this','that','to','for','and','or','with','your','you','it','its','was','were','be','can','will','these','those','from','about','into','than','then','so','but','if','as','at','by','not','no','do','does','did','has','have','had','one','ever','most','world','new','updated','latest','version','remastered','revised','recent']);

// words used purely to disguise a repost: sequence numbers, part/series markers, freshness claims
const DISGUISE_WORDS = /\b(part|pt|set|vol|volume|series|episode|ep|no|num|number|chapter|edition|version|v\d*|round|day\d*|week\d*|new|updated|latest|remastered|revised|recent|2024|2025|2026|2027)\b/g;

function stripAccents(s){
  return String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'');
}

// very light stemmer so plural/tense variants collapse to the same root
function stem(w){
  return w
    .replace(/(ing|edly)$/,'')
    .replace(/(ies)$/,'y')
    .replace(/(ed|es)$/,'')
    .replace(/s$/,'')
    .trim();
}

function normalize(s){
  let t = stripAccents(String(s || '')).toLowerCase();
  t = t.replace(/[^a-z0-9\s]/g, ' ');
  t = t.replace(/\b\d+\b/g, ' ');
  t = t.replace(DISGUISE_WORDS, ' ');
  t = t.replace(/\s+/g, ' ').trim();
  return t;
}

function tokens(s){
  return normalize(s)
    .split(' ')
    .filter(w => w.length > 2 && !STOPWORDS.has(w))
    .map(stem)
    .filter(Boolean);
}

// canonical signature: sorted unique stemmed tokens -> catches word-order shuffles
function signature(s){
  return [...new Set(tokens(s))].sort().join(' ');
}

// small non-cryptographic hash for fast fingerprint compare
function hashStr(s){
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = (Math.imul(31, h) + s.charCodeAt(i)) | 0;
  }
  return (h >>> 0).toString(36);
}

function jaccard(aTokens, bTokens){
  if (!aTokens.length || !bTokens.length) return 0;
  const a = new Set(aTokens), b = new Set(bTokens);
  let inter = 0;
  for (const w of a) if (b.has(w)) inter++;
  const union = new Set([...a, ...b]).size;
  return union ? inter / union : 0;
}

// word-bigram shingles catch paraphrases/rewrites that swap synonyms but keep sentence flow
function shingles(tokArr, n){
  const out = [];
  for (let i = 0; i <= tokArr.length - n; i++) out.push(tokArr.slice(i, i + n).join('_'));
  return out;
}

function containsOrContained(a, b){
  return a && b && (a === b || a.includes(b) || b.includes(a));
}

// ---------------- gather new content ----------------

const newTopic = String(data.topic || '');
const newTitle = String(data.title || '');
const newHook  = String(data.hook || '');
const newDesc  = String(data.description || '');
const scenes   = Array.isArray(data.scenes) ? data.scenes : [];
const newScript = scenes.map(s => String(s && s.voice || '')).join(' ');

const newTopicNorm = normalize(newTopic);
const newTopicSig  = signature(newTopic);
const newTitleSig  = signature(newTitle);
const newHookSig   = signature(newHook);
const newConceptSig = signature(`${newTopic} ${newTitle} ${newHook}`);

const newTopicTokens   = tokens(newTopic);
const newTitleTokens   = tokens(newTitle);
const newHookTokens    = tokens(newHook);
const newScriptTokens  = tokens(newScript);
const newScriptShingles = shingles(newScriptTokens, 3);

const newFingerprint = hashStr(newConceptSig);
const newScriptFingerprint = hashStr(signature(newScript));

// ---------------- gather history ----------------

let pastEntries = [];
try {
  const rows = $('Read Used Topics').all().map(i => i.json).filter(Boolean);
  pastEntries = rows.map(r => ({
    topic: String(r.topic || ''),
    title: String(r.title || ''),
    hook: String(r.hook || ''),
    description: String(r.description || ''),
    script: String(r.script || '')
  }));
} catch (e) {}

// ---------------- thresholds ----------------

const TITLE_TOPIC_HOOK_THRESHOLD = 0.55;
const CONCEPT_THRESHOLD          = 0.6;   // topic+title+hook combined = "same idea" check
const SCRIPT_THRESHOLD           = 0.5;   // token overlap on full narration
const SCRIPT_SHINGLE_THRESHOLD   = 0.35;  // phrase-level rewrite/paraphrase detector

let isDup = false;
let dupReason = '';
let matchedAgainst = '';

for (const p of pastEntries) {
  const pTopicNorm = normalize(p.topic);

  // Layer 1: exact / substring normalized topic match (catches numbers, prefixes, suffixes, punctuation tricks)
  if (newTopicNorm && pTopicNorm && containsOrContained(newTopicNorm, pTopicNorm)) {
    isDup = true; dupReason = 'normalized-topic-match'; matchedAgainst = p.topic; break;
  }

  // Layer 2: canonical signature exact match (catches reordered words, disguise words, light rewrites)
  const pTopicSig = signature(p.topic);
  const pTitleSig = signature(p.title);
  const pHookSig  = signature(p.hook);
  const pConceptSig = signature(`${p.topic} ${p.title} ${p.hook}`);

  if (newTopicSig && pTopicSig && newTopicSig === pTopicSig) {
    isDup = true; dupReason = 'topic-signature-match'; matchedAgainst = p.topic; break;
  }
  if (newTitleSig && pTitleSig && newTitleSig === pTitleSig) {
    isDup = true; dupReason = 'title-signature-match'; matchedAgainst = p.title; break;
  }

  // Layer 3: fingerprint hash match on combined concept
  if (newFingerprint === hashStr(pConceptSig) && pConceptSig) {
    isDup = true; dupReason = 'concept-fingerprint-match'; matchedAgainst = p.topic; break;
  }

  // Layer 4: token-overlap similarity (title / topic / hook individually)
  const pTopicTokens = tokens(p.topic);
  const pTitleTokens = tokens(p.title);
  const pHookTokens  = tokens(p.hook);

  if (jaccard(newTopicTokens, pTopicTokens) >= TITLE_TOPIC_HOOK_THRESHOLD) { isDup = true; dupReason = 'topic-overlap'; matchedAgainst = p.topic; break; }
  if (jaccard(newTitleTokens, pTitleTokens) >= TITLE_TOPIC_HOOK_THRESHOLD) { isDup = true; dupReason = 'title-overlap'; matchedAgainst = p.title; break; }
  if (newHookTokens.length && jaccard(newHookTokens, pHookTokens) >= TITLE_TOPIC_HOOK_THRESHOLD) { isDup = true; dupReason = 'hook-overlap'; matchedAgainst = p.hook; break; }

  // Layer 5: concept-level overlap (topic+title+hook together) -- catches "same idea, different words everywhere"
  const pConceptTokens = tokens(`${p.topic} ${p.title} ${p.hook}`);
  const newConceptTokens = tokens(`${newTopic} ${newTitle} ${newHook}`);
  if (jaccard(newConceptTokens, pConceptTokens) >= CONCEPT_THRESHOLD) {
    isDup = true; dupReason = 'concept-overlap'; matchedAgainst = p.topic; break;
  }

  // Layer 6: script-level checks (only meaningful once history rows start storing "script")
  if (p.script) {
    const pScriptTokens = tokens(p.script);
    if (newScriptTokens.length && jaccard(newScriptTokens, pScriptTokens) >= SCRIPT_THRESHOLD) {
      isDup = true; dupReason = 'script-overlap'; matchedAgainst = p.topic; break;
    }
    const pScriptShingles = shingles(pScriptTokens, 3);
    if (newScriptShingles.length && jaccard(newScriptShingles, pScriptShingles) >= SCRIPT_SHINGLE_THRESHOLD) {
      isDup = true; dupReason = 'script-phrase-rewrite'; matchedAgainst = p.topic; break;
    }
    if (newScriptFingerprint === hashStr(signature(p.script))) {
      isDup = true; dupReason = 'script-fingerprint-match'; matchedAgainst = p.topic; break;
    }
  }

  // Layer 7: description overlap (thumbnail/description swap disguise)
  if (p.description && newDesc) {
    const pDescTokens = tokens(p.description);
    const newDescTokens = tokens(newDesc);
    if (jaccard(newDescTokens, pDescTokens) >= 0.65) {
      isDup = true; dupReason = 'description-overlap'; matchedAgainst = p.topic; break;
    }
  }
}

const MAX_RETRIES = 5;
let decision = 'ok';
if (isDup) {
  wf.dupAttempts++;
  // after MAX_RETRIES failed unique attempts in a row, let it through rather than stalling the run forever
  decision = (wf.dupAttempts >= MAX_RETRIES) ? 'ok' : 'dup';
} else {
  wf.dupAttempts = 0;
}

// Flag the reusable Finder's next task (only consumed if the semantic
// AI check actually runs - i.e. isDup is still false after this check).
wf.taskType = 'semanticdup';

return {
  json: {
    ...data,
    decision,
    isDup,
    dupReason,
    matchedAgainst,
    dupAttempts: wf.dupAttempts,
    script: newScript,
    scriptFingerprint: newScriptFingerprint,
    conceptFingerprint: newFingerprint
  }
};

let data = $json;
if (!data || !Array.isArray(data.scenes) || data.scenes.length === 0) {
  const cat = data && (data.topic || data.title) ? (data.topic || data.title) : 'general';
  data = {
    ...data,
    title: (data && data.title) || 'Amazing Facts',
    topic: (data && data.topic) || cat,
    hook: (data && data.hook) || 'fallback dynamic hook',
    description: (data && data.description) || `Mind-blowing ${cat} facts you never knew. Follow for daily shorts!`,
    tags: (data && Array.isArray(data.tags) && data.tags.length) ? data.tags : ['science','technology','facts','shorts','education'],
    scenes: [
      { scene:1, voice:`Here are five surprising facts about ${cat} you probably never knew.`, image_prompt:`cinematic vertical 9:16 dramatic ${cat} scene photorealistic lighting` },
      { scene:2, voice:`Scientists recently discovered something surprising about ${cat}.`, image_prompt:`cinematic vertical 9:16 laboratory discovery ${cat} dramatic lighting photorealistic` },
      { scene:3, voice:`This hidden detail about ${cat} is stranger than most people imagine.`, image_prompt:`cinematic vertical 9:16 mysterious ${cat} close up dramatic photorealistic` },
      { scene:4, voice:`Experts still debate this ${cat} mystery because the answer sounds impossible.`, image_prompt:`cinematic vertical 9:16 intense ${cat} phenomenon glowing dramatic photorealistic` },
      { scene:5, voice:`The story of ${cat} is only beginning, so follow for more.`, image_prompt:`cinematic vertical 9:16 vast dramatic ${cat} reveal glowing photorealistic` }
    ]
  };
} else {
  data = { ...data, scenes: data.scenes.map((s,i)=>({...s, scene: i+1})) };
}
return { json: data };

// Fixed: read-only error crash এড়াতে $json থেকে safely field নেওয়া হচ্ছে।
const e = $json || {};
let node='unknown', message='unknown error', wfName='Auto YouTube Shorts';
try { node = e.execution && e.execution.lastNodeExecuted ? e.execution.lastNodeExecuted : 'unknown'; } catch(err){}
try { message = (e.execution && e.execution.error && e.execution.error.message) ? String(e.execution.error.message) : JSON.stringify(e).slice(0,300); } catch(err){ message='error serialization failed'; }
try { wfName = (e.workflow && e.workflow.name) ? e.workflow.name : wfName; } catch(err){}
const log = { status:'FAILED', workflow:wfName, node, message, timestamp:new Date().toISOString() };
console.error('[ERROR LOG]', JSON.stringify(log));
return { json: log };

