parameters.jsCode:
const meta=$node("Build YT Meta").json;
let renderSec='n/a';
try{const raw=$readFileText('/tmp/render_start');const start=parseInt(String(raw||'').trim());if(!isNaN(start)){renderSec=Math.round(Date.now()/1000)-start;}}catch(e){}
const log={status:'SUCCESS',workflow:'Auto YouTube Shorts (v9)',title:meta.title,topic:meta.topic,videoId:$node("YouTube Upload (Scheduled)").json.id,publishAt:meta.publishAt,sceneCount:$node("Wait All Scenes").json.sceneCount,renderTimeSec:renderSec,timestamp:new Date().toISOString()};
console.log('[EXEC LOG]',JSON.stringify(log));
return {json:log};

// Google Trends parse + store combined trending context.
let terms = [];
try {
  const j = $input.first().json;
  const raw = String(j.data ?? j.body ?? j ?? '');
  const matches = [...raw.matchAll(/<title>(.*?)<\/title>/g)].map(m => m[1]).filter(Boolean);
  terms = matches.filter(t => !/daily search trends/i.test(t)).slice(0, 20);
} catch(e) {}
let ytTrends = [];
try { ytTrends = $node("Extract YouTube Trends").json.youtubeTrends || []; } catch(e) {}
const wf = $getWorkflowStaticData('global');
const combined = [...new Set([...ytTrends, ...terms])].filter(Boolean).slice(0, 15);
wf.trendingContext = combined.join(' | ');
return [{ json: { googleTrends: terms, trendingContextStored: wf.trendingContext } }];

let obscureTopics = [];
try {
  const list = $input.first().json.query?.random || [];
  obscureTopics = list.map(x => x.title).filter(Boolean);
} catch(e) { obscureTopics = []; }

// filter out titles that make bad 45s Shorts fodder: lists, disambiguation, pure place/admin stubs
const BAD = /^(list of|category:|template:|disambiguation|index of)/i;
obscureTopics = obscureTopics.filter(t => !BAD.test(t));

return [{ json: { obscureTopics: obscureTopics.join(', ') } }];

let titles = [];
try {
  const body = $input.first().json;
  const items = body.items || [];
  titles = items.map(v => v.snippet && v.snippet.title).filter(Boolean).slice(0, 20);
} catch(e) {}
return [{ json: { youtubeTrends: titles } }];

// CODE-FIRST grammar + QC validation. Deterministic only - no AI, no
// network call here. Flags (a) grammar/QC issues, and (b) up to 2 specific,
// checkable factual claims for the next node (Lightweight Fact Lookup) to
// verify online. The actual AI-need decision is made after that lookup.
const d = $json;
const issues = [];

// --- QC: required fields / schema -----------------------------------------
if (!d.title) issues.push('missing_title');
if (!d.topic) issues.push('missing_topic');
if (!d.description) issues.push('missing_description');
if (!Array.isArray(d.tags) || d.tags.length === 0) issues.push('missing_tags');
if (!Array.isArray(d.scenes) || d.scenes.length !== 5) issues.push('bad_scene_count');

const scenes = Array.isArray(d.scenes) ? d.scenes : [];

// --- Grammar/QC: per-scene deterministic checks + claim extraction --------
const factClaims = [];
scenes.forEach((s, i) => {
  const voice = String((s && s.voice) || '').trim();
  const img = String((s && s.image_prompt) || '').trim();

  if (!voice) { issues.push(`scene_${i + 1}_empty_voice`); return; }
  if (!img) issues.push(`scene_${i + 1}_empty_image_prompt`);

  const wc = voice.split(/\s+/).filter(Boolean).length;
  if (wc < 10 || wc > 30) issues.push(`scene_${i + 1}_word_count_${wc}`);

  if (/\s{2,}/.test(voice)) issues.push(`scene_${i + 1}_double_space`);
  if (!/[.!?]$/.test(voice)) issues.push(`scene_${i + 1}_no_terminal_punctuation`);
  if (/\b(\w+)\s+\1\b/i.test(voice)) issues.push(`scene_${i + 1}_repeated_word`);
  if (/^[a-z]/.test(voice)) issues.push(`scene_${i + 1}_not_capitalized`);

  // A scene carrying a specific number or a two-word capitalized entity is
  // worth a genuine fact-check pass; pure narrative filler is not.
  // Capture the actual matched text as the online search term (bounded to
  // the first 2 claims found across the whole script - keeps the next
  // node's network usage small and predictable).
  if (factClaims.length < 2) {
    const entityMatch = voice.match(/\b[A-Z][a-z]+\s+[A-Z][a-z]+\b/);
    const numberMatch = voice.match(/\b\d{2,}\b[^.?!]*/);
    const term = entityMatch ? entityMatch[0] : (numberMatch ? `${d.topic || ''} ${numberMatch[0]}`.trim() : null);
    if (term) factClaims.push({ scene: i + 1, searchTerm: term.slice(0, 100) });
  }
});

const grammarPass = issues.length === 0;
const qcPass = !issues.some(i => i.startsWith('missing_') || i === 'bad_scene_count');

return { json: {
  title: d.title,
  topic: d.topic,
  hook: d.hook || (scenes[0] ? scenes[0].voice : ''),
  description: d.description,
  tags: d.tags,
  scenes,
  factCheckApplied: false,
  grammarPass,
  qcPass,
  qcIssues: issues,
  factClaims
} };

// REAL lightweight ONLINE verification for factual claims the deterministic
// pass flagged - not AI. Uses Wikipedia's public search API (free, no auth,
// tiny JSON, short timeout). Bounded to at most 2 lookups per run.
//
// PASS      = a claim's search term matched a clearly-relevant article.
// FAIL      = a claim's search term returned zero results at all (strong
//             lightweight signal the named entity/claim doesn't exist).
// UNCERTAIN = ambiguous match, lookup error, or claim genuinely needs a
//             judgment call this simple lookup can't make -> AI last resort.
//
// If deterministic checks found no checkable claim, no network call is made
// at all and this is an immediate PASS.
const d = $json;
const claims = Array.isArray(d.factClaims) ? d.factClaims.slice(0, 2) : [];

async function lookup(term) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://en.wikipedia.org/w/api.php',
      qs: { action: 'query', list: 'search', srsearch: term, srlimit: 1, format: 'json' },
      timeout: 4000,
      json: true
    });
    const hits = (res && res.query && Array.isArray(res.query.search)) ? res.query.search : [];
    if (!hits.length) return 'no-match';
    const claimTokens = new Set(String(term).toLowerCase().split(/\s+/).filter(w => w.length > 3));
    const titleTokens = String(hits[0].title || '').toLowerCase().split(/\s+/);
    return titleTokens.some(w => claimTokens.has(w)) ? 'match' : 'weak-match';
  } catch (e) {
    return 'lookup-error';
  }
}

let results = [];
let factStatus = 'PASS';
let factCheckSkippedReason = 'no-claim-detected';

if (claims.length && this && this.helpers && typeof this.helpers.httpRequest === 'function') {
  factCheckSkippedReason = null;
  for (const c of claims) {
    results.push({ scene: c.scene, term: c.searchTerm, result: lookup.call(this, c.searchTerm) });
  }
  const outcomes = results.map(r => r.result);
  if (outcomes.some(o => o === 'match')) {
    factStatus = 'PASS';
  } else if (outcomes.length && outcomes.every(o => o === 'no-match')) {
    factStatus = 'FAIL';
  } else {
    factStatus = 'UNCERTAIN'; // weak-match / lookup-error / mixed -> genuinely unresolved
  }
} else if (claims.length) {
  // httpRequest helper unavailable in this runtime - fail safe to UNCERTAIN
  // rather than silently skipping verification or crashing the run.
  factStatus = 'UNCERTAIN';
  factCheckSkippedReason = 'httpRequest-helper-unavailable';
}

// AI is invoked ONLY when grammar failed deterministically, or the online
// verification above could not confidently resolve the claim (UNCERTAIN).
// A successful PASS or FAIL never triggers AI.
const needsAiCheck = !d.grammarPass || factStatus === 'UNCERTAIN';

if (needsAiCheck) {
  // Flag the reusable Finder's next task in workflow static data (survives
  // the Loop Wait retry loop untouched, unlike the item chain).
  $getWorkflowStaticData('global').taskType = 'factgrammar';
}

return { json: {
  title: d.title,
  topic: d.topic,
  hook: d.hook,
  description: d.description,
  tags: d.tags,
  scenes: d.scenes,
  factCheckApplied: false,
  grammarPass: d.grammarPass,
  qcPass: d.qcPass,
  qcIssues: d.qcIssues,
  factStatus,
  factCheckSkippedReason,
  factLookupResults: results,
  needsAiCheck
} };

let aiDup = false;
let aiReason = '';
let aiMatched = '';
try {
  const raw = $json?.candidates?.[0]?.content?.parts?.[0]?.text
      ?? $json?.choices?.[0]?.message?.content
      ?? '';
  const cleaned = String(raw).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  const parsed = JSON.parse(cleaned);
  aiDup = !!parsed.duplicate;
  aiReason = String(parsed.reason || '');
  aiMatched = String(parsed.matched || '');
} catch (e) {
  // if the AI check itself fails/errors, do NOT block the pipeline on it -- heuristic Dedupe Check already ran
  aiDup = false;
  aiReason = 'ai-check-unavailable';
}

const prev = $node("Dedupe Check").json;
const finalIsDup = prev.isDup || aiDup;
const finalDecision = finalIsDup && prev.dupAttempts < 5 ? 'dup' : 'ok';

return {
  json: {
    ...prev,
    aiDup,
    aiReason,
    aiMatched,
    decision: finalDecision
  }
};

const wf = $getWorkflowStaticData('global');
if (typeof wf.modelAttempt !== 'number') wf.modelAttempt = 0;

// ---- Provider circuit-breaker state (existing static data: wf.providerState) ----
// Entry: { provider, status:'cooldown', reason, cooldownUntil, execId, setAt }
// cooldownUntil = provider's reset timestamp (survives executions until it passes).
// No reset timestamp -> execution-scoped: valid only for this execution id (30 min cap),
// so a stale entry can never disable a provider permanently.
let execId = 'na';
try { execId = String(($execution && $execution.id) || 'na'); } catch (e) { execId = 'na'; }
function providerBlocked(p) {
  const st = wf.providerState && wf.providerState[p];
  if (!st) return false;
  const now = Date.now();
  if (st.cooldownUntil) {
    if (now < st.cooldownUntil) return true;
  } else if (st.execId === execId && (now - (st.setAt || 0)) < 30 * 60 * 1000) {
    return true;
  }
  delete wf.providerState[p];
  return false;
}
// Validate Attempt sets retrySame for the single allowed transient retry: same model, no re-discovery.
const isRetry = wf.retrySame === true;
wf.retrySame = false;
const taskType = wf.taskType || 'script';

// ---------------------------------------------------------------------------
// SHARED MODEL FINDER - the ONE reusable instance for every AI checkpoint in
// this workflow (Script Writer, Fact & Grammar Checker, AI Semantic Duplicate
// Check). Do not create a second Finder anywhere else.
//
// AUTOMATIC RUNTIME DISCOVERY (no permanently-disabled providers):
// every provider below is checked, every run: (1) required credential(s)
// present via env, (2) the provider's own metadata/models endpoint is queried
// to see what is CURRENTLY listed, (3) that live result is intersected with
// this file's documented free-tier candidates (or, for OpenRouter/Together,
// filtered directly on the provider's own live $0 pricing field - no
// candidate list needed at all). A provider that cannot currently prove a
// free model contributes ZERO entries to the queue and is skipped THIS RUN
// only - nothing is hardcoded off. If a provider's pricing/availability
// changes tomorrow, tomorrow's discovery reflects that automatically.
//
// Two verification tiers, both computed live, never assumed:
//   'live-pricing'                      - the provider's own API returns a
//                                          numeric per-model price; only
//                                          entries priced exactly 0/0 pass.
//                                          Verified current official
//                                          endpoints that expose this today:
//                                          OpenRouter (GET /api/v1/models,
//                                          pricing.prompt/completion),
//                                          Together (GET /v1/models,
//                                          pricing.input/output), DeepInfra
//                                          (GET api.deepinfra.com/models/list,
//                                          public/keyless native catalog,
//                                          pricing.cents_per_input_token/
//                                          cents_per_output_token),
//                                          Hugging Face router (GET
//                                          router.huggingface.co/v1/models,
//                                          per-provider pricing.input/output
//                                          in USD/M tokens plus an is_free
//                                          promo flag), and SambaNova (GET
//                                          /v1/models, pricing.prompt/
//                                          completion - confirmed in
//                                          SambaNova's published OpenAPI
//                                          spec).
//   'existence-probe+documented-free'   - the provider's API does not expose
//                                          machine-readable pricing, so we
//                                          probe that our documented
//                                          candidate model is CURRENTLY
//                                          listed/enabled for this credential
//                                          (proves it isn't renamed/removed/
//                                          gated) and combine that with a
//                                          maintained free-tier record.
//                                          Used today for Google Gemini,
//                                          Cerebras, Groq, and Cloudflare
//                                          Workers AI (whose free daily
//                                          Neuron allocation is documented,
//                                          not per-model priced).
// A provider with neither signal available returns zero models -> UNKNOWN
// -> BLOCKED for this run, every run, until a real discovery signal exists.
//
// Providers are tried in this fixed priority order. ALL verified-free models
// of a provider are exhausted before moving to the next provider. The first
// model that returns a valid result (see Validate Attempt) wins immediately.
//
// ZERO-BILLING HARD LOCK: never a paid, trial-credit-only, unknown-price, or
// auto/default/best/latest/pro/premium-routed model, ever, as primary,
// fallback, or last resort. See finalBillingGuard() below - it runs on every
// single candidate before it can ever become an actual HTTP request.
// ---------------------------------------------------------------------------
const BILLING_MODE = 'free_only';
const PROVIDER_ORDER = ['openrouter', 'google', 'cerebras', 'groq', 'huggingface', 'deepinfra', 'together', 'sambanova', 'cloudflare'];
const PROVIDER_ALLOWLIST = new Set(PROVIDER_ORDER);
const APPROVED_ENDPOINTS = new Set(PROVIDER_ORDER);
// Router/auto-selector "models" are never a fixed, audited model - block by
// exact id regardless of any reported price.
const ROUTER_MODEL_DENYLIST = new Set(['openrouter/free', 'openrouter/auto', 'openrouter/auto-beta']);
// Blocks any model id containing a standalone auto/default/best/latest/pro/
// premium/paid token (word-boundary on typical model-id punctuation), e.g.
// "gemini-2.5-pro" or "openai/gpt-5-pro" - but NOT substrings inside a real
// word (does not false-positive on things like "processor" or "protocol").
const FORBIDDEN_MODEL_PATTERN = /(^|[\/\-_.:\s])(auto|default|best|latest|pro|premium|paid)([\/\-_.:\s]|$)/i;
const AUTH_ENV_BY_TYPE = {
  openrouter: 'OPENROUTER_API_KEY',
  cerebras: 'CEREBRAS_API_KEY',
  groq: 'GROQ_API_KEY',
  cloudflare: 'CLOUDFLARE_API_TOKEN',
  huggingface: 'HF_TOKEN',
  deepinfra: 'DEEPINFRA_API_KEY',
  together: 'TOGETHER_API_KEY',
  sambanova: 'SAMBANOVA_API_KEY'
  // google uses x-goog-api-key (GEMINI_API_KEY), handled separately below -
  // it must never be sent as a Bearer Authorization value or a URL param.
};
const CHAT_ENDPOINTS = {
  openrouter: 'https://openrouter.ai/api/v1/chat/completions',
  cerebras: 'https://api.cerebras.ai/v1/chat/completions',
  groq: 'https://api.groq.com/openai/v1/chat/completions',
  // Verified against router.huggingface.co's own OpenAI-compatible chat
  // completions docs. Model id must be sent as "<modelId>:<providerName>"
  // (e.g. "zai-org/GLM-5.3:baseten") - discoverHuggingFace() below builds
  // candidates in exactly that composite form.
  huggingface: 'https://router.huggingface.co/v1/chat/completions',
  // Verified against DeepInfra's official chat docs (docs.deepinfra.com).
  deepinfra: 'https://api.deepinfra.com/v1/openai/chat/completions',
  // Verified against Together's current official docs (docs.together.ai).
  together: 'https://api.together.ai/v1/chat/completions',
  // Verified against SambaNova's published OpenAPI spec (docs.sambanova.ai).
  sambanova: 'https://api.sambanova.ai/v1/chat/completions'
  // google and cloudflare are built dynamically (model-in-path / account-id-
  // in-path respectively) in the request-building block below.
};

// Never leak a raw error (which could echo request context) - reduce every
// discovery failure to a fixed, non-secret reason string.
async function httpGetJson(helpers, url, headers, timeoutMs) {
  try {
    const res = await helpers.httpRequest({ method: 'GET', url, headers: headers || {}, timeout: timeoutMs || 7000, json: true });
    return { ok: true, data: res };
  } catch (e) {
    return { ok: false };
  }
}

// --- Tier: live-pricing (the provider's own API returns a numeric price) ---

async function discoverOpenRouter(helpers, env) {
  if (!env.OPENROUTER_API_KEY) return { available: false, reason: 'missing-credential', models: [] };
  const r = await httpGetJson(helpers, 'https://openrouter.ai/api/v1/models', { Authorization: `Bearer ${env.OPENROUTER_API_KEY}` });
  if (!r.ok || !r.data || !Array.isArray(r.data.data)) return { available: false, reason: 'discovery-unavailable', models: [] };
  const models = r.data.data
    .filter(m => m && typeof m.id === 'string' && m.pricing
      && Number(m.pricing.prompt) === 0 && Number(m.pricing.completion) === 0
      && !ROUTER_MODEL_DENYLIST.has(m.id))
    .map(m => m.id)
    .slice(0, 20);
  return { available: models.length > 0, reason: models.length ? null : 'no-verified-zero-price-model', models, tier: 'live-pricing' };
}

async function discoverTogether(helpers, env) {
  if (!env.TOGETHER_API_KEY) return { available: false, reason: 'missing-credential', models: [] };
  // api.together.ai is Together's current documented domain (docs.together.ai/reference/models);
  // api.together.xyz remains a live alias but api.together.ai is what's verified official today.
  const r = await httpGetJson(helpers, 'https://api.together.ai/v1/models', { Authorization: `Bearer ${env.TOGETHER_API_KEY}` });
  if (!r.ok || !Array.isArray(r.data)) return { available: false, reason: 'discovery-unavailable', models: [] };
  const models = r.data
    .filter(m => m && typeof m.id === 'string' && m.pricing
      && Number(m.pricing.input) === 0 && Number(m.pricing.output) === 0)
    .map(m => m.id)
    .slice(0, 20);
  return { available: models.length > 0, reason: models.length ? null : 'no-model-with-verified-zero-price', models, tier: 'live-pricing' };
}

// --- Tier: existence-probe + documented free-tier (no live pricing field) ---

async function discoverGoogle(helpers, env) {
  if (!env.GEMINI_API_KEY) return { available: false, reason: 'missing-credential', models: [] };
  const r = await httpGetJson(helpers, 'https://generativelanguage.googleapis.com/v1beta/models', { 'x-goog-api-key': env.GEMINI_API_KEY });
  if (!r.ok || !r.data || !Array.isArray(r.data.models)) return { available: false, reason: 'discovery-unavailable', models: [] };
  const liveIds = new Set(r.data.models.map(m => String((m && m.name) || '').replace(/^models\//, '')));
  // gemini-2.5-pro is intentionally NEVER in this list - see FORBIDDEN_MODEL_PATTERN for the executable guard too.
  const FREE_TIER_CANDIDATES = ['gemini-2.5-flash-lite', 'gemini-2.5-flash'];
  const models = FREE_TIER_CANDIDATES.filter(id => liveIds.has(id));
  return { available: models.length > 0, reason: models.length ? null : 'no-verified-candidate-currently-listed', models, tier: 'existence-probe+documented-free' };
}

async function discoverCerebras(helpers, env) {
  if (!env.CEREBRAS_API_KEY) return { available: false, reason: 'missing-credential', models: [] };
  const r = await httpGetJson(helpers, 'https://api.cerebras.ai/v1/models', { Authorization: `Bearer ${env.CEREBRAS_API_KEY}` });
  if (!r.ok || !r.data || !Array.isArray(r.data.data)) return { available: false, reason: 'discovery-unavailable', models: [] };
  const liveIds = new Set(r.data.data.map(m => m && m.id));
  const FREE_TIER_CANDIDATES = ['llama-3.3-70b', 'qwen-3-32b', 'llama-4-scout-17b-16e-instruct', 'deepseek-r1-distill-llama-70b'];
  const models = FREE_TIER_CANDIDATES.filter(id => liveIds.has(id));
  return { available: models.length > 0, reason: models.length ? null : 'no-verified-candidate-currently-listed', models, tier: 'existence-probe+documented-free' };
}

async function discoverGroq(helpers, env) {
  if (!env.GROQ_API_KEY) return { available: false, reason: 'missing-credential', models: [] };
  const r = await httpGetJson(helpers, 'https://api.groq.com/openai/v1/models', { Authorization: `Bearer ${env.GROQ_API_KEY}` });
  if (!r.ok || !r.data || !Array.isArray(r.data.data)) return { available: false, reason: 'discovery-unavailable', models: [] };
  const liveIds = new Set(r.data.data.map(m => m && m.id));
  const FREE_TIER_CANDIDATES = ['llama-3.3-70b-versatile', 'llama-3.1-8b-instant', 'openai/gpt-oss-120b', 'openai/gpt-oss-20b', 'meta-llama/llama-4-scout-17b-16e-instruct', 'qwen/qwen3-32b'];
  const models = FREE_TIER_CANDIDATES.filter(id => liveIds.has(id));
  return { available: models.length > 0, reason: models.length ? null : 'no-verified-candidate-currently-listed', models, tier: 'existence-probe+documented-free' };
}

async function discoverCloudflare(helpers, env) {
  if (!env.CLOUDFLARE_API_TOKEN || !env.CLOUDFLARE_ACCOUNT_ID) return { available: false, reason: 'missing-credential', models: [] };
  const url = `https://api.cloudflare.com/client/v4/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/ai/models/search?per_page=100`;
  const r = await httpGetJson(helpers, url, { Authorization: `Bearer ${env.CLOUDFLARE_API_TOKEN}` });
  if (!r.ok || !r.data || r.data.success !== true || !Array.isArray(r.data.result)) return { available: false, reason: 'discovery-unavailable', models: [] };
  const liveIds = new Set(r.data.result.map(m => m && m.name));
  const FREE_TIER_CANDIDATES = ['@cf/meta/llama-3.1-8b-instruct-fast', '@cf/meta/llama-3.3-70b-instruct-fp8-fast', '@cf/qwen/qwen3-30b-a3b-fp8'];
  const models = FREE_TIER_CANDIDATES.filter(id => liveIds.has(id));
  // Cloudflare Workers AI Free plan: requests beyond the daily neuron quota
  // are REJECTED, never auto-billed - satisfies fail-closed billing safety
  // even without a live per-model USD price field.
  return { available: models.length > 0, reason: models.length ? null : 'no-verified-candidate-currently-listed', models, tier: 'existence-probe+free-quota-not-auto-billed' };
}

// --- Tier: live-pricing, verified 2026 against each provider's own docs ---
// Hugging Face, DeepInfra and SambaNova each expose real machine-readable
// per-model pricing today (confirmed against current official docs/OpenAPI
// specs below) - none of them are "no endpoint" placeholders any more.

async function discoverHuggingFace(helpers, env) {
  if (!env.HF_TOKEN) return { available: false, reason: 'missing-credential', models: [] };
  // Verified: huggingface.co/docs/inference-providers/hub-api#list-openai-compatible-models
  // Each model lists one entry per serving provider; a provider entry may carry
  // pricing.input/output (USD per million tokens) and/or is_free (temporary
  // promo flag). We treat either signal as proof of FREE - never trial credit.
  const r = await httpGetJson(helpers, 'https://router.huggingface.co/v1/models', { Authorization: `Bearer ${env.HF_TOKEN}` });
  if (!r.ok || !r.data || !Array.isArray(r.data.data)) return { available: false, reason: 'discovery-unavailable', models: [] };
  const models = [];
  for (const m of r.data.data) {
    if (!m || typeof m.id !== 'string' || !Array.isArray(m.providers)) continue;
    for (const p of m.providers) {
      if (!p || p.status !== 'live' || typeof p.provider !== 'string') continue;
      const isFreePromo = p.is_free === true;
      const isZeroPriced = p.pricing && Number(p.pricing.input) === 0 && Number(p.pricing.output) === 0;
      if (isFreePromo || isZeroPriced) {
        // HF router requires the provider to be pinned in the model id itself.
        models.push(`${m.id}:${p.provider}`);
      }
    }
  }
  return { available: models.length > 0, reason: models.length ? null : 'no-verified-zero-price-model', models: models.slice(0, 20), tier: 'live-pricing' };
}

async function discoverDeepInfra(helpers, env) {
  if (!env.DEEPINFRA_API_KEY) return { available: false, reason: 'missing-credential', models: [] };
  // Verified: docs.deepinfra.com/chat/overview (chat endpoint) and DeepInfra's
  // public, keyless native catalog at api.deepinfra.com/models/list, which -
  // unlike the OpenAI-compatible /v1/openai/models listing - reports real
  // per-token pricing (cents_per_input_token / cents_per_output_token).
  const r = await httpGetJson(helpers, 'https://api.deepinfra.com/models/list', {});
  if (!r.ok || !Array.isArray(r.data)) return { available: false, reason: 'discovery-unavailable', models: [] };
  const models = r.data
    .filter(m => m && typeof m.model_name === 'string'
      && (m.type === 'text-generation' || m.reported_type === 'text-generation')
      && !m.deprecated
      && m.pricing && Number(m.pricing.cents_per_input_token) === 0 && Number(m.pricing.cents_per_output_token) === 0)
    .map(m => m.model_name)
    .slice(0, 20);
  return { available: models.length > 0, reason: models.length ? null : 'no-verified-zero-price-model', models, tier: 'live-pricing' };
}

async function discoverSambaNova(helpers, env) {
  if (!env.SAMBANOVA_API_KEY) return { available: false, reason: 'missing-credential', models: [] };
  // Verified: docs.sambanova.ai OpenAPI spec for GET /v1/models - each
  // ModelMetadata entry carries pricing.prompt / pricing.completion (USD per
  // token). SambaNova's account-level "no card required" offer is a one-time
  // trial credit, NOT a recurring free tier, so credit alone is never treated
  // as FREE here - only a model actually priced at 0/0 in this live response is.
  const r = await httpGetJson(helpers, 'https://api.sambanova.ai/v1/models', { Authorization: `Bearer ${env.SAMBANOVA_API_KEY}` });
  if (!r.ok || !r.data || !Array.isArray(r.data.data)) return { available: false, reason: 'discovery-unavailable', models: [] };
  const models = r.data.data
    .filter(m => m && typeof m.id === 'string' && m.pricing
      && Number(m.pricing.prompt) === 0 && Number(m.pricing.completion) === 0)
    .map(m => m.id)
    .slice(0, 20);
  return { available: models.length > 0, reason: models.length ? null : 'no-verified-zero-price-model', models, tier: 'live-pricing' };
}

const DISCOVERERS = {
  openrouter: discoverOpenRouter,
  google: discoverGoogle,
  cerebras: discoverCerebras,
  groq: discoverGroq,
  huggingface: discoverHuggingFace,
  deepinfra: discoverDeepInfra,
  together: discoverTogether,
  sambanova: discoverSambaNova,
  cloudflare: discoverCloudflare
};

async function buildFreeQueue(helpers, env) {
  const settled = await Promise.allSettled(PROVIDER_ORDER.map(p => providerBlocked(p) ? Promise.resolve({ available: false, models: [] }) : DISCOVERERS[p](helpers, env)));
  const queue = [];
  for (let i = 0; i < PROVIDER_ORDER.length; i++) {
    const providerType = PROVIDER_ORDER[i];
    const outcome = settled[i];
    const disc = (outcome.status === 'fulfilled' && outcome.value) ? outcome.value : { available: false, models: [] };
    if (disc.available && Array.isArray(disc.models)) {
      for (const modelId of disc.models) {
        queue.push({ provider: providerType, type: providerType, model: modelId, tier: disc.tier || 'unverified', verifiedFree: true });
      }
    }
  }
  return queue;
}

// Final, executable, pre-HTTP billing guard. Runs on every candidate before
// it can ever be selected as `current` - not just once at startup. ALL of
// these must hold or the candidate is skipped, never called.
function finalBillingGuard(candidate, env) {
  if (!candidate) return { pass: false, reason: 'no-candidate' };
  if (!PROVIDER_ALLOWLIST.has(candidate.provider)) return { pass: false, reason: 'provider-not-allowlisted' };
  if (candidate.verifiedFree !== true) return { pass: false, reason: 'not-verified-free' };
  if (BILLING_MODE !== 'free_only') return { pass: false, reason: 'billing-mode-not-free-only' };
  if (!APPROVED_ENDPOINTS.has(candidate.type)) return { pass: false, reason: 'endpoint-not-approved' };
  if (typeof candidate.model !== 'string' || !candidate.model.trim().length) return { pass: false, reason: 'invalid-model' };
  if (ROUTER_MODEL_DENYLIST.has(candidate.model)) return { pass: false, reason: 'router-model-denied' };
  if (FORBIDDEN_MODEL_PATTERN.test(candidate.model)) return { pass: false, reason: 'forbidden-routing-token' };
  if (candidate.type === 'google') {
    if (!(env.GEMINI_API_KEY && String(env.GEMINI_API_KEY).trim().length)) return { pass: false, reason: 'missing-credential' };
  } else if (candidate.type === 'cloudflare') {
    if (!(env.CLOUDFLARE_API_TOKEN && String(env.CLOUDFLARE_API_TOKEN).trim().length)) return { pass: false, reason: 'missing-credential' };
    if (!(env.CLOUDFLARE_ACCOUNT_ID && String(env.CLOUDFLARE_ACCOUNT_ID).trim().length)) return { pass: false, reason: 'missing-credential' };
  } else {
    const authEnvVar = AUTH_ENV_BY_TYPE[candidate.type];
    if (!authEnvVar || !(env[authEnvVar] && String(env[authEnvVar]).trim().length)) return { pass: false, reason: 'missing-credential' };
  }
  return { pass: true };
}

// Rebuild discovery only at the start of a fresh task-attempt sequence
// (modelAttempt reset to 0 by Validate Attempt on the previous task's
// success/failed_all) or when the cache is missing/belongs to a different
// taskType. Mid-task retries (modelAttempt > 0) reuse the already-discovered
// queue instead of re-querying all 9 providers on every single retry - the
// data is still "at the time of execution" for this task, just not
// re-fetched on every loop tick within it.
const needsRebuild = (wf.modelAttempt === 0 && !isRetry) || !wf.freeQueueCache || wf.freeQueueCache.taskType !== taskType;
let modelQueue;
if (needsRebuild) {
  wf.transientTried = null;
  const helpers = this.helpers;
  modelQueue = (helpers && typeof helpers.httpRequest === 'function') ? await buildFreeQueue(helpers, $env) : [];
  // Only non-secret metadata is ever cached - no credential value is stored.
  wf.freeQueueCache = { taskType, queue: modelQueue, builtAt: Date.now() };
} else {
  modelQueue = wf.freeQueueCache.queue;
}

// billing guard + provider circuit breaker: a cooled-down/disabled provider's remaining models are skipped wholesale.
while (wf.modelAttempt < modelQueue.length && (!finalBillingGuard(modelQueue[wf.modelAttempt], $env).pass || providerBlocked(modelQueue[wf.modelAttempt].provider))) {
  wf.modelAttempt++;
}

// all FREE models across all providers exhausted (or none currently verify
// as free/available) -> clean failure state. Validate Attempt routes this
// straight to each task's own deterministic fallback - never a paid model
// call - and tags the result resultType: 'DETERMINISTIC_FALLBACK' so it can
// never be mistaken for a real AI success.
if (wf.modelAttempt >= modelQueue.length) {
  wf.modelAttempt = 0;
  wf.freeQueueCache = null;
  wf.transientTried = null;
  return { json: { loopStatus: 'failed_all', resultType: 'DETERMINISTIC_FALLBACK', failureCode: 'NO_FREE_PROVIDER_AVAILABLE', taskType } };
}

const current = modelQueue[wf.modelAttempt];


// ---------------------------------------------------------------------------
// Task-specific prompt. Only the prompt text + response shape differ between
// checkpoints; model/provider selection and request plumbing are shared.
// ---------------------------------------------------------------------------
let promptText;
let googleGenerationConfig;
let orTemperature, orMaxTokens, orPresencePenalty;

if (taskType === 'factgrammar') {
