function isValidScriptShape(data, expectedSceneCount){
  if (!data || typeof data !== 'object') return false;
  if (!data.title || typeof data.title !== 'string' || !data.title.trim()) return false;
  if (!data.topic || typeof data.topic !== 'string' || !data.topic.trim()) return false;
  if (!data.description || typeof data.description !== 'string' || !data.description.trim()) return false;
  if (!Array.isArray(data.tags) || data.tags.length === 0) return false;
  if (!Array.isArray(data.scenes)) return false;
  const want = (typeof expectedSceneCount === 'number' && expectedSceneCount > 0) ? expectedSceneCount : 5;
  if (data.scenes.length !== want) return false;
  return data.scenes.every(s => s
    && typeof s.voice === 'string' && s.voice.trim().length > 0
    && typeof s.image_prompt === 'string' && s.image_prompt.trim().length > 0);
}

