function classifyError(body, provider) {
  let raw = '';
  try { raw = String((body.error && body.error.message) || '') + ' ' + JSON.stringify(body.error).slice(0, 4000); } catch (e) { raw = errMsg; }
  const low = raw.toLowerCase();
  let code = NaN;
  const e = (body && body.error) || {};
  for (const v of [e.httpCode, e.status, e.statusCode, e.code]) { const n = Number(v); if (n >= 100 && n <= 599) { code = n; break; } }
  if (isNaN(code)) { const m = String(e.message || '').match(/^\s*(\d{3})\b/) || low.match(/"code"\W{1,4}(\d{3})\b/); if (m) code = Number(m[1]); }
  if (provider === 'openrouter') {
    const rem = low.match(/x-ratelimit-remaining\W{1,8}(\d+)/);
    const rst = low.match(/x-ratelimit-reset\W{1,8}(\d{10,13})/);
    let resetTs = null;
    if (rst) { resetTs = Number(rst[1]); if (rst[1].length <= 10) resetTs *= 1000; }
    const quota = low.includes('free-models-per-day') || low.includes('openrouter_free_tier_daily') || (code === 429 && rem && Number(rem[1]) === 0);
    if (quota) return { cls: 'provider_quota', skipProvider: true, retryable: false, resetTs, reason: 'free_quota_exhausted' };
  }
  if (code === 401 || code === 402 || (code === 403 && /key|auth|permission|credential|forbidden|unauthori/.test(low))) {
    return { cls: 'provider_auth', skipProvider: true, retryable: false, resetTs: null, reason: 'auth_or_billing_rejected' };
  }
  if ((code >= 500 && code <= 599) || code === 408 || /timeout|timed out|etimedout|esockettimedout|econnreset|econnrefused|socket hang up/.test(low)) {
    return { cls: 'transient', skipProvider: false, retryable: true, resetTs: null, reason: 'transient' };
  }
  return { cls: 'model_error', skipProvider: false, retryable: false, resetTs: null, reason: 'model_error' }; // 4xx incl. plain 429/404 -> next model, 0 retry
}

