  return finish({ imageStatus: 'ok', imageProvider: provider, imageModel: model, imageCanonical: ctl.canonical, imageFreeEvidence: ctl.verificationTier, imageAttempts: ctl.attempt, imageLatencyMs: rec.lastLatency });
}

rec.failureCount += 1; rec.lastFailure = NOW;
if (verdict.cls === 'quota') {
  const until = resetFor(provider, verdict.resetTs);
  rec.status = verdict.payment ? 'payment_required' : 'quota_exhausted';
  rec.quotaState = 'exhausted'; rec.quotaResetAt = verdict.payment ? Math.max(until, NOW + 24 * HOUR) : until; rec.cooldownUntil = 0;
  if (verdict.wide) blockProvider(provider, rec.quotaResetAt, 'quota_exhausted', true);   // account-wide: no point trying siblings
} else if (verdict.cls === 'rate') {
  const wait = Math.min(Math.max(verdict.resetTs ? verdict.resetTs - NOW : 0, 30000), 15 * 60000);
  if (KEYLESS[provider]) blockProvider(provider, NOW + wait, 'degraded', false);          // anonymous limit is per-IP, not per-model
  else { rec.status = 'degraded'; rec.cooldownUntil = NOW + wait; }
} else if (verdict.cls === 'auth') {
  if (KEYLESS[provider]) { rec.status = 'auth_blocked'; rec.cooldownUntil = NOW + 24 * HOUR; }
  else blockProvider(provider, NOW + HOUR, 'auth_blocked', false);
} else if (verdict.cls === 'unsupported') {
  rec.status = 'unsupported'; rec.cooldownUntil = NOW + 6 * HOUR;
} else if (verdict.cls === 'invalid' && rec.successCount === 0 && provider !== 'pollinations') {
  // verified FREE but never produced a storable image (typically base64 JSON output): a capability gap, NOT paid / NOT non-free.
  // Only this model is set aside (re-probed automatically after 24h); the provider stays available for its other FREE models.
  rec.status = UNSUPPORTED; rec.cooldownUntil = NOW + 24 * HOUR;
} else {
  ladder(rec);
}

if (verdict.cls === 'invalid' && ctl.canonical) S.failedCanon[ctl.canonical] = 1;   // same underlying model elsewhere would give the same bad output
if (S.attempts >= MAX_SCENE_ATTEMPTS) {
  return finish({ imageStatus: 'failed_all', imageFailureCode: 'ATTEMPT_CAP', lastError: verdict.cls });
}
return { json: { decision: 'loop', failedProvider: provider, failedModel: model, errorClass: verdict.cls, attempt: S.attempts } };

// Fail-fast validation of the single Google Sheets configuration source: GOOGLE_SHEETS_URL (full spreadsheet URL incl. the target tab's gid).
//   https://docs.google.com/spreadsheets/d/<SPREADSHEET_ID>/edit#gid=<TAB_GID>
// This runs before any Sheets read/write. The MicroFlow engine's Google Sheets executor derives the spreadsheet ID from the same
// variable and resolves gid -> exact tab name with the connected Google account (a Code node has no authenticated Google access).
// There is NO fallback (no first tab, no default range): any problem stops the execution with GOOGLE_SHEETS_CONFIG_ERROR.
const url = String(($env && $env.GOOGLE_SHEETS_URL) || '').trim();
if (!url) {
  throw new Error('GOOGLE_SHEETS_CONFIG_ERROR: environment variable GOOGLE_SHEETS_URL is missing. Set it to the full Google Spreadsheet URL including the target sheet gid (https://docs.google.com/spreadsheets/d/<ID>/edit#gid=<TAB_ID>).');
}
if (!/^https:\/\/docs\.google\.com\/spreadsheets\/(?:u\/\d+\/)?d\/[A-Za-z0-9_-]{20,}/.test(url)) {
  throw new Error('GOOGLE_SHEETS_CONFIG_ERROR: GOOGLE_SHEETS_URL is not a valid Google Spreadsheet URL (spreadsheet ID could not be extracted; expected https://docs.google.com/spreadsheets/d/<ID>/...).');
}
if (!/[#&?]gid=\d+/.test(url)) {
  throw new Error('GOOGLE_SHEETS_CONFIG_ERROR: GOOGLE_SHEETS_URL must include the target sheet gid (e.g. ...#gid=123456789). No default or first-tab fallback is used.');
}
return [{ json: Object.assign({}, $json) }];

// Google Sheets cells must be scalars. Every field of the row is normalized deterministically before the Sheets node:
//   null/undefined -> ''   | string/number/boolean -> unchanged   | array of scalars -> "a,b,c"
//   nested array/object -> compact JSON string   | each cell capped (bounded) below the Sheets per-cell limit
// Field names and their order are preserved, so the sheet column layout is unchanged.
const MAX_CELL = 45000;
const cap = (s) => (s.length > MAX_CELL ? s.slice(0, MAX_CELL) : s);
function isScalar(x) { const t = typeof x; return t === 'string' || t === 'number' || t === 'boolean'; }
function scalar(v) {
  if (v === null || v === undefined) return '';
  const t = typeof v;
  if (t === 'string') return cap(v);
  if (t === 'number') return isFinite(v) ? v : '';
  if (t === 'boolean') return v;
  if (v instanceof Date) return v.toISOString();
  if (Array.isArray(v)) {
    let simple = true;
    for (let i = 0; i < v.length; i++) { if (!isScalar(v[i])) { simple = false; break; } }
    if (simple) { const parts = []; for (let i = 0; i < v.length; i++) parts.push(String(v[i])); return cap(parts.join(',')); }
  }
  try { const s = JSON.stringify(v); return s === undefined ? '' : cap(s); } catch (e) { return cap(String(v)); }
}
const src = $json || {};
const out = {};
for (const k of Object.keys(src)) out[k] = scalar(src[k]);
return [{ json: out }];

